```php
private static function safe_exception_path( string $path ): string {
	if ( '' === $path || '?' === $path ) {
		return '?';
	}

	$normalized_path = wp_normalize_path( $path );
	$root            = wp_normalize_path( ABSPATH );

	if ( 0 === strpos( $normalized_path, $root ) ) {
		return ltrim( substr( $normalized_path, strlen( $root ) ), '/' );
	}

	return basename( $normalized_path );
}

private static function sanitize_trace_frame( mixed $frame ): string {
	if ( ! is_string( $frame ) ) {
		return '?';
	}

	return preg_replace_callback(
		'/^(.+?):(\d+)/',
		static function ( array $matches ): string {
			return self::safe_exception_path( $matches[1] ) . ':' . $matches[2];
		},
		$frame
	) ?? $frame;
}
```
