+			return new WP_Error( 'missing_prompt', 'Prompt is required for image generation.' );
+		}
+
+		// Add size hints to the prompt.
+		$full_prompt = $prompt;
+		if ( $width > 0 && $height > 0 ) {
+			$full_prompt = sprintf(
