+class ModelsCommand extends WP_CLI_Command {
+
+	/**
+	 * List AI providers and models.
+	 *
+	 * Without --provider, prints one row per provider with model count.
+	 * With --provider, prints one row per model for that provider.
+	 *
+	 * ## OPTIONS
+	 *
+	 * [--provider=<id>]
