+		$allowed_user_fields = [ 'status', 'pinned', 'folder' ];
+		$allowed_fields      = [ 'status', 'pinned', 'folder', 'updated_at' ];
+
+		$data = array_intersect_key( $data, array_flip( $allowed_user_fields ) );
+		if ( empty( $data ) ) {
+			return 0;
+		}
+		$data['updated_at'] = current_time( 'mysql', true );
```
